// AI: below section was generated by an AI
/*
 * MQTT Rules usermod
 *
 * Lets the board react to MQTT messages and publish MQTT events using rules stored in a file,
 * so no rule has to be compiled into the firmware and almost no RAM is used for them.
 *
 * Rules file: /mqttrules.jsonl  (JSON Lines: one rule per line, max MR_LINE_MAX characters)
 *
 *  Message rule  (runs when a message arrives on a subscribed topic):
 *    {"k":"m","n":"name","e":1,"t":"%dev%/cmd/#","o":"=","v":"on","a":"{...JSON API...}","d":10,"r":"{\"ps\":210}","pt":"%dev%/ack","pp":"done {p}"}
 *  Event rule    (runs when the board changes state):
 *    {"k":"e","n":"name","e":1,"ev":"ps|pw|br","o":"*","pt":"%dev%/event","pp":"preset {n}"}
 *
 *  t   topic filter (+ and # wildcards, %dev% = WLED device topic)
 *  o   payload/value condition: * any, = equals, c contains, > greater, < smaller, r range "a,b"
 *  v   value for the condition
 *  a   JSON API command to execute; {p} = payload (JSON-escaped), {n} = payload as integer
 *  d,r after d seconds execute JSON API command r (e.g. go back to the clock)
 *  b   1 = instead of r, go back to the preset/playlist that was running before the rule's action
 *      (r is the fallback when nothing was running)
 *  w   1 = wait until the Scrolling Text effect finishes one pass before going back
 *      (d is then only the display time of text that fits the matrix and does not scroll)
 *  pt,pp publish pp (placeholders {p} {n}) on topic pt after running the rule
 *  ev  event source: ps = preset applied ({n} = preset id), pw = power (payload on/off), br = brightness ({n})
 *
 *  Timed rule    (runs at a time / interval / when temperature or humidity changes):
 *    {"k":"t","n":"name","tm":450,"iv":15,"tf":480,"tt":1320,"dw":62,"vr":"t","o":">","v":"28","a":"{...}","pt":"%dev%/hora","pp":"{hm} {t}"}
 *  Value source  (stores a number published on a topic as temperature "t" or humidity "h"):
 *    {"k":"v","n":"Temperatura","vr":"t","t":"home/room/temp"}
 *
 *  tm  minute of the day to fire at (0..1439); iv = fire every N minutes (only inside tf..tt, minutes of the day, when given)
 *  dw  weekday mask, bit 0 = Sunday (default 127 = every day)
 *  vr,o,v  condition on the value "t" or "h" (same operators as above); without tm/iv the rule fires when the condition
 *      becomes true and re-arms when it turns false
 *  extra placeholders: {t} {h} temperature / humidity, {hm} HH:MM, {dw} weekday (0 = Sunday)
 *
 * Control through the JSON state API (/json/state):
 *    {"mqttr":{"set":{"t":23.5,"h":60}}}             provide temperature / humidity from another source
 *    {"mqttr":{"reload":1}}                          re-read rules file and re-subscribe
 *    {"mqttr":{"test":{"t":"topic","p":"payload"}}}  simulate an incoming message (works without a broker)
 *    {"mqttr":{"icon":"whatsapp","sec":6}}           draw a notification icon over the matrix for sec seconds (mqtt_icons.h);
 *                                                    usable as a rule action. It does not change effects, presets or on/off.
 * Status is added to /json/info as "mqttr": {"n":rules,"hits":count,"con":connected,"log":[...]}
 */
#include "wled.h"

#ifndef WLED_DISABLE_MQTT

#include "mqtt_icons.h"

#define MR_FILE        "/mqttrules.jsonl"
#define MR_LINE_MAX    760   // max length of one rule line
#define MR_DOC_SIZE    1024  // JSON document used to parse one rule
#define MR_ACTION_MAX  420   // max length of an expanded action
#define MR_Q           4     // incoming message queue depth
#define MR_TOPIC_MAX   64
#define MR_PAYLOAD_MAX 112
#define MR_SUBS        10    // max subscribed rule topics
#define MR_SUB_LEN     48
#define MR_LOG_N       6
#define MR_LOG_LEN     84
#define MR_WAIT_MAX    180000UL // longest wait for a scrolling text to finish (ms)

namespace {

struct MrMsg { char t[MR_TOPIC_MAX]; char p[MR_PAYLOAD_MAX]; };

// --- MQTT topic filter matching with + and # wildcards -------------------------------------------
bool topicMatch(const char* f, const char* t) {
  for (;;) {
    if (*f == '#') return true;
    if (*f == '+') {
      while (*t && *t != '/') t++;
      f++;
    } else {
      while (*f && *f != '/' && *t && *t != '/') { if (*f != *t) return false; f++; t++; }
      if ((*f && *f != '/') || (*t && *t != '/')) return false; // one side ended inside the level
    }
    if (*f == 0) return *t == 0;
    if (*f != '/' || *t != '/') return false;
    f++; t++;
    if (*f == 0) return *t == 0;
  }
}

bool containsNoCase(const char* hay, const char* needle) {
  size_t n = strlen(needle);
  if (n == 0) return true;
  for (; *hay; hay++) if (strncasecmp(hay, needle, n) == 0) return true;
  return false;
}

// payload/value condition of a rule
bool condOk(const char* op, const char* v, const char* p) {
  char o = (op && op[0]) ? op[0] : '*';
  if (!v) v = "";
  switch (o) {
    case '=': return strcasecmp(p, v) == 0;
    case 'c': return containsNoCase(p, v);
    case '>': return atof(p) > atof(v);
    case '<': return atof(p) < atof(v);
    case 'r': { float a = atof(v); const char* c = strchr(v, ','); float b = c ? atof(c + 1) : a; float x = atof(p); return x >= a && x <= b; }
    default:  return true;
  }
}

// values the timed rules can test: 0 = temperature, 1 = humidity (set by a "v" rule or through the JSON state API)
float gVar[2] = {0, 0};
bool gHas[2] = {false, false};
int gMd = -1, gDw = 0; // current minute of the day (-1 = clock not set) and weekday (0 = Sunday)

uint8_t varIdx(const char* s) { return (s && s[0] == 't' && !s[1]) ? 0 : (s && s[0] == 'h' && !s[1]) ? 1 : 255; }

void fmtVar(uint8_t i, char* b, size_t n) {
  if (i > 1 || !gHas[i]) snprintf(b, n, "--");
  else if (gVar[i] == (float)(long)gVar[i]) snprintf(b, n, "%ld", (long)gVar[i]);
  else snprintf(b, n, "%.1f", (double)gVar[i]);
}

// replace %dev% by the device topic (topics) and {p} / {n} by the payload; {t} {h} {hm} {dw} = temperature, humidity, HH:MM, weekday (0 = Sunday)
void expand(const char* tpl, char* out, size_t n, const char* payload, bool jsonEscape) {
  size_t o = 0;
  for (const char* c = tpl; *c && o + 1 < n;) {
    if (c[0] == '{' && (c[1] == 't' || c[1] == 'h') && c[2] == '}') {
      char b[12]; fmtVar(c[1] == 't' ? 0 : 1, b, sizeof(b));
      o += snprintf(out + o, n - o, "%s", b);
      if (o >= n) o = n - 1;
      c += 3;
    } else if (strncmp(c, "{hm}", 4) == 0) {
      if (gMd >= 0) o += snprintf(out + o, n - o, "%02d:%02d", gMd / 60, gMd % 60); else o += snprintf(out + o, n - o, "--:--");
      if (o >= n) o = n - 1;
      c += 4;
    } else if (strncmp(c, "{dw}", 4) == 0) {
      o += snprintf(out + o, n - o, "%d", gDw);
      if (o >= n) o = n - 1;
      c += 4;
    } else if (c[0] == '{' && c[1] == 'p' && c[2] == '}') {
      for (const char* q = payload; *q && o + 2 < n; q++) {
        if ((uint8_t)*q < 0x20) continue;
        if (jsonEscape && (*q == '"' || *q == '\\')) out[o++] = '\\';
        if (o + 1 < n) out[o++] = *q;
      }
      c += 3;
    } else if (c[0] == '{' && c[1] == 'n' && c[2] == '}') {
      o += snprintf(out + o, n - o, "%ld", strtol(payload, nullptr, 10));
      if (o >= n) o = n - 1;
      c += 3;
    } else if (strncmp(c, "%dev%", 5) == 0) {
      o += snprintf(out + o, n - o, "%s", mqttDeviceTopic);
      if (o >= n) o = n - 1;
      c += 5;
    } else out[o++] = *c++;
  }
  out[o] = 0;
}

} // namespace

class MqttRulesUsermod : public Usermod {
  private:
    MrMsg _q[MR_Q];
    volatile uint8_t _qh = 0, _qt = 0;
    char _subs[MR_SUBS][MR_SUB_LEN];
    uint8_t _nsubs = 0;
    char* _revert = nullptr;
    unsigned long _revertAt = 0;
    // "go back" support: what was running before the first temporary action of a rule, and the
    // wait-for-scrolling-text state (a pass of the Scrolling Text effect ends when its offset wraps to 0)
    int16_t _prevPl = -1, _prevPs = 0;
    bool _useMem = false, _wait = false;
    unsigned long _wtStart = 0, _wtChg = 0;
    int32_t _wtLast = -1;
    char _log[MR_LOG_N][MR_LOG_LEN];
    uint8_t _logN = 0, _logHead = 0;
    uint16_t _rules = 0, _hits = 0;
    bool _reload = true, _evDirty = false, _test = false;
    MrMsg _testMsg;
    int _lastPs = -1, _lastBri = -1, _lastOn = -1;
    bool _first = true;
    bool _varDirty = false, _tickDue = false;
    uint32_t _armed = 0, _lastMin = 0; // _armed: bit per rule (first 32) of the value-triggered timed rules whose condition is currently true
    // notification icon drawn as an overlay: needs no GIF decoder and leaves the running effect or playlist alone
    int8_t _icon = -1;
    unsigned long _icoStart = 0, _icoDur = 0, _icoTrig = 0;

    // starts the named icon for some seconds; an unknown or empty name removes the current one
    void showIcon(const char* name, int seconds) {
      _icon = -1;
      for (uint8_t i = 0; i < sizeof(mrIcons) / sizeof(mrIcons[0]); i++) {
        if (strcmp_P(name, mrIcons[i].name) == 0) { _icon = i; break; }
      }
      _icoStart = millis(); _icoDur = (unsigned long)constrain(seconds, 1, 120) * 1000UL;
      strip.trigger();
    }

    void addLog(const char* kind, const char* a, const char* b) {
      snprintf(_log[_logHead], MR_LOG_LEN, "%lus %s %s%s%s", millis() / 1000, kind, a, b && *b ? " = " : "", b ? b : "");
      _logHead = (_logHead + 1) % MR_LOG_N; if (_logN < MR_LOG_N) _logN++;
    }

    // reads the next line of the rules file; returns false at the end
    static bool nextLine(File& f, char* buf, size_t n) {
      while (f.available()) {
        size_t len = f.readBytesUntil('\n', buf, n - 1);
        buf[len] = 0;
        if (len == n - 1) { while (f.available() && f.read() != '\n') {} } // line too long: ignore the rest
        while (len && (buf[len - 1] == '\r' || buf[len - 1] == ' ')) buf[--len] = 0;
        if (len > 1 && buf[0] == '{') return true;
      }
      return false;
    }

    bool runJson(const char* json) {
      if (!requestJSONBufferLock(JSON_LOCK_UNKNOWN)) return false;
      DeserializationError err = deserializeJson(*pDoc, json);
      if (!err) deserializeState(pDoc->as<JsonObject>(), CALL_MODE_DIRECT_CHANGE);
      releaseJSONBufferLock();
      return !err;
    }

    void publishTo(const char* topicTpl, const char* payloadTpl, const char* payload) {
      if (!topicTpl || !*topicTpl || !WLED_MQTT_CONNECTED) return;
      char t[MR_TOPIC_MAX + 16], p[MR_PAYLOAD_MAX + 48];
      expand(topicTpl, t, sizeof(t), payload, false);
      expand(payloadTpl ? payloadTpl : "", p, sizeof(p), payload, false);
      mqtt->publish(t, 0, false, p);
    }

    // runs the action/revert/publish parts of one rule
    void runRule(JsonObject r, const char* payload) {
      const char* a = r["a"] | "";
      int d = r["d"] | 0; const char* rv = r["r"] | "";
      bool back = d > 0 && *rv;
      if (back && !_revert) { _prevPl = currentPlaylist; _prevPs = currentPreset; } // only before the first temporary action
      if (*a) {
        char* out = (char*)malloc(MR_ACTION_MAX);
        if (out) { expand(a, out, MR_ACTION_MAX, payload, true); if (!runJson(out)) addLog("ERRO", "JSON da regra invalido", ""); free(out); }
      }
      if (back) {
        free(_revert); _revert = (char*)malloc(MR_ACTION_MAX);
        if (_revert) {
          expand(rv, _revert, MR_ACTION_MAX, payload, true);
          _revertAt = millis() + (unsigned long)d * 1000UL;
          _useMem = (r["b"] | 0) != 0; _wait = (r["w"] | 0) != 0;
          _wtStart = _wtChg = millis(); _wtLast = -1;
        }
      }
      publishTo(r["pt"] | "", r["pp"] | "", payload);
    }

    // true when the temporary action may be undone: timer expired or, in wait mode, the scrolling text finished one pass
    bool revertDue() {
      unsigned long now = millis();
      bool timer = (long)(now - _revertAt) >= 0;
      if (!_wait) return timer;
      if (now - _wtStart > MR_WAIT_MAX) return true;
      if (now - _wtStart < 1200) return false; // let the segment switch effects (its runtime counters restart)
      const Segment& s = strip.getSegment(0);
      if (s.mode != FX_MODE_2DSCROLLTEXT) return timer;
      int32_t a = s.aux0;
      if (_wtLast < 0) { _wtLast = a; _wtChg = now; return false; }
      if (a != _wtLast) { bool wrapped = a < _wtLast; _wtLast = a; _wtChg = now; return wrapped; }
      return timer && now - _wtChg > 1500; // text that fits the matrix does not scroll: show it for the configured time
    }

    // undoes the temporary action: back to what was running before, or to the rule's fallback preset
    void doRevert() {
      char* r = _revert; _revert = nullptr;
      char b[24] = "";
      if (_useMem) {
        if (_prevPl >= 0) snprintf(b, sizeof(b), "{\"ps\":%d}", (int)_prevPl);
        else if (_prevPs > 0) snprintf(b, sizeof(b), "{\"ps\":%d}", (int)_prevPs);
      }
      runJson(b[0] ? b : r); free(r);
    }

    // finds and runs the message rules that match topic/payload
    void handleMessage(const char* topic, const char* payload) {
      File f = WLED_FS.open(MR_FILE, "r"); if (!f) return;
      char* line = (char*)malloc(MR_LINE_MAX);
      DynamicJsonDocument* doc = new DynamicJsonDocument(MR_DOC_SIZE);
      if (!line || !doc) { free(line); delete doc; f.close(); return; }
      char full[MR_TOPIC_MAX + MR_SUB_LEN], ft[MR_SUB_LEN + 24];
      uint16_t idx = 0; bool any = false;
      while (nextLine(f, line, MR_LINE_MAX)) {
        idx++;
        doc->clear();
        if (deserializeJson(*doc, line)) continue;
        JsonObject r = doc->as<JsonObject>();
        const char* kind = r["k"] | "m";
        bool isVar = strcmp(kind, "v") == 0;
        if ((!isVar && strcmp(kind, "m") != 0) || !(r["e"] | 1)) continue;
        expand(r["t"] | "", ft, sizeof(ft), "", false);
        bool ok = topicMatch(ft, topic);
        if (!ok && topic[0] == '/') { // WLED strips its own prefix from device/group topics
          snprintf(full, sizeof(full), "%s%s", mqttDeviceTopic, topic); ok = topicMatch(ft, full);
          if (!ok && mqttGroupTopic[0]) { snprintf(full, sizeof(full), "%s%s", mqttGroupTopic, topic); ok = topicMatch(ft, full); }
        }
        if (!ok) continue;
        if (isVar) { // sensor binding: remember the number so timed rules can test it
          uint8_t vi = varIdx(r["vr"] | "");
          if (vi < 2 && (payload[0] == '-' || payload[0] == '.' || (payload[0] >= '0' && payload[0] <= '9'))) { setVar(vi, atof(payload)); any = true; addLog(vi ? "umidade:" : "temperatura:", topic, payload); }
          continue;
        }
        if (!condOk(r["o"] | "*", r["v"] | "", payload)) continue;
        any = true; _hits++;
        char tag[40]; snprintf(tag, sizeof(tag), "regra %u:", idx);
        addLog(tag, topic, payload);
        runRule(r, payload);
      }
      if (!any) addLog("sem regra:", topic, payload);
      f.close(); free(line); delete doc;
    }

    void setVar(uint8_t i, float v) { gVar[i] = v; gHas[i] = true; _varDirty = true; }

    // runs the timed rules ("k":"t"). tm = minute of day to fire at, or iv = every N minutes (optionally only inside tf..tt);
    // dw = weekday mask (bit 0 = Sunday); vr/o/v = condition on temperature ("t") or humidity ("h").
    // Without tm/iv a rule is triggered by the value changing: it fires when the condition becomes true and re-arms when it turns false.
    void handleTimed(bool varChange) {
      File f = WLED_FS.open(MR_FILE, "r"); if (!f) return;
      char* line = (char*)malloc(MR_LINE_MAX);
      DynamicJsonDocument* doc = new DynamicJsonDocument(MR_DOC_SIZE);
      if (!line || !doc) { free(line); delete doc; f.close(); return; }
      uint16_t idx = 0;
      while (nextLine(f, line, MR_LINE_MAX)) {
        idx++;
        doc->clear();
        if (deserializeJson(*doc, line)) continue;
        JsonObject r = doc->as<JsonObject>();
        if (strcmp(r["k"] | "", "t") != 0 || !(r["e"] | 1)) continue;
        uint8_t vi = varIdx(r["vr"] | "");
        int tm = r["tm"] | -1, iv = r["iv"] | 0, dw = r["dw"] | 127, tf = r["tf"] | -1, tt = r["tt"] | -1;
        bool timed = tm >= 0 || iv > 0;
        bool dayOk = gMd >= 0 ? ((dw >> gDw) & 1) : dw == 127;
        bool winOk = (tf < 0 || tt < 0) ? true : gMd < 0 ? false : (tf <= tt ? (gMd >= tf && gMd <= tt) : (gMd >= tf || gMd <= tt));
        char val[16] = ""; bool condTrue = true;
        if (vi < 2) { fmtVar(vi, val, sizeof(val)); condTrue = gHas[vi] && condOk(r["o"] | "*", r["v"] | "", val); }
        if (timed) {
          if (varChange || gMd < 0) continue;
          bool hit = (tm >= 0 && gMd == tm) || (iv > 0 && gMd % iv == 0 && winOk);
          if (!hit || !dayOk || !condTrue) continue;
        } else {
          if (!varChange || vi > 1) continue;
          uint32_t bit = idx <= 32 ? (1UL << (idx - 1)) : 0;
          bool wasArmed = (_armed & bit) != 0;
          if (!condTrue) { _armed &= ~bit; continue; }
          if (wasArmed || !dayOk || !winOk) continue;
          _armed |= bit;
        }
        char pl[16];
        if (vi < 2) strlcpy(pl, val, sizeof(pl)); else snprintf(pl, sizeof(pl), "%02d:%02d", gMd / 60, gMd % 60);
        _hits++;
        char tag[40]; snprintf(tag, sizeof(tag), "hora %u:", idx);
        addLog(tag, "disparou", pl);
        runRule(r, pl);
      }
      f.close(); free(line); delete doc;
    }

    // runs the event rules (ev = "ps"/"pw"/"br") for a changed value
    void handleEvent(const char* ev, const char* value) {
      File f = WLED_FS.open(MR_FILE, "r"); if (!f) return;
      char* line = (char*)malloc(MR_LINE_MAX);
      DynamicJsonDocument* doc = new DynamicJsonDocument(MR_DOC_SIZE);
      if (!line || !doc) { free(line); delete doc; f.close(); return; }
      uint16_t idx = 0;
      while (nextLine(f, line, MR_LINE_MAX)) {
        idx++;
        doc->clear();
        if (deserializeJson(*doc, line)) continue;
        JsonObject r = doc->as<JsonObject>();
        if (strcmp(r["k"] | "", "e") != 0 || !(r["e"] | 1) || strcmp(r["ev"] | "", ev) != 0) continue;
        if (!condOk(r["o"] | "*", r["v"] | "", value)) continue;
        _hits++;
        char tag[40]; snprintf(tag, sizeof(tag), "evento %u:", idx);
        addLog(tag, ev, value);
        runRule(r, value);
      }
      f.close(); free(line); delete doc;
    }

    // (re)subscribes to the topics of the message rules; drops subscriptions that are no longer used
    void subscribeAll() {
      char old[MR_SUBS][MR_SUB_LEN]; uint8_t nold = _nsubs;
      memcpy(old, _subs, sizeof(old)); _nsubs = 0; _rules = 0;
      File f = WLED_FS.open(MR_FILE, "r");
      if (f) {
        char* line = (char*)malloc(MR_LINE_MAX);
        DynamicJsonDocument* doc = new DynamicJsonDocument(MR_DOC_SIZE);
        if (line && doc) {
          char ft[MR_SUB_LEN + 24];
          while (nextLine(f, line, MR_LINE_MAX)) {
            _rules++;
            doc->clear();
            if (deserializeJson(*doc, line)) continue;
            JsonObject r = doc->as<JsonObject>();
            const char* kind = r["k"] | "m";
            if ((strcmp(kind, "m") != 0 && strcmp(kind, "v") != 0) || !(r["e"] | 1)) continue;
            expand(r["t"] | "", ft, sizeof(ft), "", false);
            if (!ft[0] || strlen(ft) >= MR_SUB_LEN) continue;
            bool dup = false;
            for (uint8_t i = 0; i < _nsubs; i++) if (strcmp(_subs[i], ft) == 0) { dup = true; break; }
            if (!dup && _nsubs < MR_SUBS) strlcpy(_subs[_nsubs++], ft, MR_SUB_LEN);
          }
        }
        f.close(); free(line); delete doc;
      }
      if (!WLED_MQTT_CONNECTED) return;
      for (uint8_t i = 0; i < nold; i++) {
        bool keep = false;
        for (uint8_t j = 0; j < _nsubs; j++) if (strcmp(old[i], _subs[j]) == 0) { keep = true; break; }
        if (!keep) mqtt->unsubscribe(old[i]);
      }
      for (uint8_t i = 0; i < _nsubs; i++) mqtt->subscribe(_subs[i], 0);
    }

  public:
    void setup() override {}

    void loop() override {
      if (_icon >= 0) { // keep frames coming while an icon is shown, even over a static effect
        unsigned long now = millis();
        if (now - _icoStart >= _icoDur) { _icon = -1; strip.trigger(); }
        else if (now - _icoTrig >= 60) { _icoTrig = now; strip.trigger(); }
      }
      if (_reload) { _reload = false; subscribeAll(); }
      if (_revert && revertDue()) doRevert();
      if (localTime > 1704067200UL) { // clock is set (after 2024-01-01)
        uint32_t m = localTime / 60;
        if (m != _lastMin) { bool first = _lastMin == 0; _lastMin = m; gMd = hour(localTime) * 60 + minute(localTime); gDw = weekday(localTime) - 1; if (!first) _tickDue = true; }
      } else gMd = -1;
      if (_tickDue) { _tickDue = false; handleTimed(false); return; }
      if (_varDirty) { _varDirty = false; handleTimed(true); return; }
      if (_test) { _test = false; handleMessage(_testMsg.t, _testMsg.p); return; }
      if (_qh != _qt) { MrMsg m = _q[_qt]; _qt = (_qt + 1) % MR_Q; handleMessage(m.t, m.p); return; }
      if (_evDirty) { // detect which part of the state changed
        _evDirty = false;
        int on = bri > 0 ? 1 : 0; char v[12];
        if (_first) { _first = false; _lastPs = currentPreset; _lastBri = bri; _lastOn = on; return; }
        if (on != _lastOn) { _lastOn = on; handleEvent("pw", on ? "on" : "off"); }
        if (bri != _lastBri) { _lastBri = bri; snprintf(v, sizeof(v), "%u", bri); handleEvent("br", v); }
        if ((int)currentPreset != _lastPs) { _lastPs = currentPreset; snprintf(v, sizeof(v), "%u", currentPreset); handleEvent("ps", v); }
      }
    }

    void onMqttConnect(bool sessionPresent) override { _reload = true; }

    bool onMqttMessage(char* topic, char* payload) override {
      uint8_t nh = (_qh + 1) % MR_Q;
      if (nh == _qt) return false; // queue full: drop
      strlcpy(_q[_qh].t, topic, MR_TOPIC_MAX); strlcpy(_q[_qh].p, payload ? payload : "", MR_PAYLOAD_MAX);
      _qh = nh;
      return false; // other usermods may still handle the message
    }

    void onStateChange(uint8_t mode) override { _evDirty = true; }

    // paints the current icon frame, centred (and enlarged by whole factors on big matrices) on a black background
    void handleOverlayDraw() override {
#ifndef WLED_DISABLE_2D
      if (_icon < 0 || !strip.isMatrix) return;
      MrIcon ic; memcpy_P(&ic, &mrIcons[_icon], sizeof(ic));
      uint32_t total = 0;
      for (uint8_t i = 0; i < MR_ICON_STEPS; i++) total += ic.delay[i] * 10;
      uint32_t t = (millis() - _icoStart) % total;
      uint8_t step = 0;
      while (step < MR_ICON_STEPS - 1 && t >= ic.delay[step] * 10U) t -= ic.delay[step++] * 10U;
      const uint8_t* px = ic.px + (size_t)ic.frame[step] * MR_ICON_SIZE * MR_ICON_SIZE;
      const int w = Segment::maxWidth, h = Segment::maxHeight;
      const int scale = max(1, min(w, h) / MR_ICON_SIZE), size = MR_ICON_SIZE * scale;
      const int x0 = (w - size) / 2, y0 = (h - size) / 2;
      for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) {
        int ix = x - x0, iy = y - y0;
        uint32_t c = 0;
        if (ix >= 0 && iy >= 0 && ix < size && iy < size) c = pgm_read_dword(ic.pal + pgm_read_byte(px + (iy / scale) * MR_ICON_SIZE + ix / scale));
        strip.setPixelColor((unsigned)(y * w + x), c);
      }
#endif
    }

    void readFromJsonState(JsonObject& root) override {
      JsonObject o = root["mqttr"]; if (o.isNull()) return;
      if (o["reload"]) _reload = true;
      if (!o["icon"].isNull()) showIcon(o["icon"] | "", o["sec"] | 6);
      JsonObject sv = o["set"]; // {"t":23.5,"h":60}: temperature / humidity from another source (for example the Clock tool's weather)
      if (!sv.isNull()) {
        if (!sv["t"].isNull()) setVar(0, sv["t"].as<float>());
        if (!sv["h"].isNull()) setVar(1, sv["h"].as<float>());
      }
      JsonObject t = o["test"];
      if (!t.isNull()) { strlcpy(_testMsg.t, t["t"] | "", MR_TOPIC_MAX); strlcpy(_testMsg.p, t["p"] | "", MR_PAYLOAD_MAX); _test = true; }
    }

    void addToJsonInfo(JsonObject& root) override {
      JsonObject o = root.createNestedObject("mqttr");
      o["n"] = _rules; o["hits"] = _hits; o["con"] = WLED_MQTT_CONNECTED; o["subs"] = _nsubs;
      o["clk"] = gMd >= 0; // false until the board knows the time
      o["ico"] = 1; // this firmware can draw notification icons
      if (gHas[0]) o["vt"] = gVar[0];
      if (gHas[1]) o["vh"] = gVar[1];
      JsonArray l = o.createNestedArray("log");
      for (uint8_t i = 0; i < _logN; i++) l.add(_log[(_logHead + MR_LOG_N - 1 - i) % MR_LOG_N]); // newest first
    }

    uint16_t getId() override { return USERMOD_ID_UNSPECIFIED; }
};

static MqttRulesUsermod mqttRulesUsermod;
REGISTER_USERMOD(mqttRulesUsermod);

#endif // WLED_DISABLE_MQTT
